    ('msg.pr_the_file_could_not_be_read_use_the_template_xlsx_or_a_cs', 'msg', N'The file could not be read. Use the template (.xlsx) or a .csv file.', N'تعذرت قراءة الملف. استخدم النموذج (.xlsx) أو ملف ‎.csv.', N'The file could not be read. Use the template (.xlsx) or a .csv file.'),
    ('msg.pr_the_file_has_no_rows_to_import', 'msg', N'The file has no rows to import.', N'لا توجد صفوف في الملف للاستيراد.', N'The file has no rows to import.'),
    ('msg.pr_the_file_is_larger_than_5_mb', 'msg', N'The file is larger than 5 MB.', N'حجم الملف أكبر من 5 ميجابايت.', N'The file is larger than 5 MB.'),
    ('msg.pr_the_import_failed_nothing_was_imported', 'msg', N'The import failed - nothing was imported.', N'فشل الاستيراد - لم يُستورد شيء.', N'The import failed - nothing was imported.'),
    ('msg.pr_the_item_type_of_a_salary_item_cannot_be_changed_delete', 'msg', N'The item type of a salary item cannot be changed. Delete it and add a new one.', N'لا يمكن تغيير نوع بند الراتب. احذفه وأضف بنداً جديداً.', N'The item type of a salary item cannot be changed. Delete it and add a new one.'),
    ('msg.pr_the_last_month_cannot_be_before_a_month_already_paid', 'msg', N'The last month cannot be before a month already paid.', N'لا يمكن أن يكون آخر شهر قبل شهر تم صرفه.', N'The last month cannot be before a month already paid.'),
    ('msg.pr_the_last_month_cannot_be_before_the_first_month', 'msg', N'The last month cannot be before the first month.', N'لا يمكن أن يكون آخر شهر قبل أول شهر.', N'The last month cannot be before the first month.'),
    ('msg.pr_the_payroll_can_only_be_recalculated_while_it_is_registe', 'msg', N'The payroll can only be recalculated while it is Registered.', N'لا يمكن إعادة احتساب المسير إلا وهو بحالة «مُسجّل».', N'The payroll can only be recalculated while it is Registered.'),
    ('msg.pr_the_payroll_is_back_in_the_register', 'msg', N'The payroll is back in the register.', N'عاد المسير إلى الكشف.', N'The payroll is back in the register.'),
    ('msg.pr_the_payroll_of_that_month_is_already_closed_choose_a_lat', 'msg', N'The payroll of that month is already closed. Choose a later month, or add the line to an off-cycle payroll.', N'مسير رواتب ذلك الشهر مغلق. اختر شهراً لاحقاً، أو أضف السطر إلى مسير رواتب خارج الدورة.', N'The payroll of that month is already closed. Choose a later month, or add the line to an off-cycle payroll.'),
    ('msg.pr_the_salary_change_that_replaced_it_was_deleted_this_amou', 'msg', N'The salary change that replaced it was deleted - this amount applies again', N'حُذف تغيير الراتب الذي استبدله - يسري هذا المبلغ مجدداً', N'The salary change that replaced it was deleted - this amount applies again'),
    ('msg.pr_there_are_no_employees_in_this_payroll', 'msg', N'There are no employees in this payroll.', N'لا يوجد موظفون في هذا المسير.', N'There are no employees in this payroll.'),
    ('msg.pr_this_employee_already_has_a_change_of_this_item_waiting', 'msg', N'This employee already has a change of this item waiting for approval.', N'لدى هذا الموظف تغيير على هذا البند بانتظار الاعتماد بالفعل.', N'This employee already has a change of this item waiting for approval.'),
    ('msg.pr_this_employee_number_is_in_more_than_one_company_choose', 'msg', N'This employee number is in more than one company - choose one company at the top first.', N'هذا الرقم الوظيفي موجود في أكثر من شركة - اختر شركة واحدة من الأعلى أولاً.', N'This employee number is in more than one company - choose one company at the top first.'),
    ('msg.pr_this_item_has_already_been_paid_by_a_payroll_and_cannot', 'msg', N'This item has already been paid by a payroll and cannot be deleted. End it instead.', N'صُرف هذا البند في مسير رواتب ولا يمكن حذفه. أنهِه بدلاً من ذلك.', N'This item has already been paid by a payroll and cannot be deleted. End it instead.'),
    ('msg.pr_this_item_has_already_been_paid_by_a_payroll_only_its_co', 'msg', N'This item has already been paid by a payroll. Only its comment and last month can be changed - end it and add a new item instead.', N'صُرف هذا البند في مسير رواتب. يمكن تعديل الملاحظة وآخر شهر فقط - أنهِه وأضف بنداً جديداً بدلاً من ذلك.', N'This item has already been paid by a payroll. Only its comment and last month can be changed - end it and add a new item instead.'),
    ('msg.pr_this_item_has_ended_and_cannot_be_changed', 'msg', N'This item has ended and cannot be changed.', N'انتهى هذا البند ولا يمكن تعديله.', N'This item has ended and cannot be changed.'),
    ('msg.pr_this_item_is_not_waiting_for_approval', 'msg', N'This item is not waiting for approval.', N'هذا البند ليس بانتظار الاعتماد.', N'This item is not waiting for approval.'),
    ('msg.pr_this_item_type_is_inactive_activate_it_in_payroll_settin', 'msg', N'This item type is inactive. Activate it in Payroll Settings or choose another.', N'نوع البند هذا غير نشط. فعّله من إعدادات الرواتب أو اختر نوعاً آخر.', N'This item type is inactive. Activate it in Payroll Settings or choose another.'),
    ('msg.pr_this_item_was_approved_by_someone_else_meanwhile_the_lis', 'msg', N'This item was approved by someone else meanwhile. The list has been refreshed.', N'اعتمد شخص آخر هذا البند في الأثناء. تم تحديث القائمة.', N'This item was approved by someone else meanwhile. The list has been refreshed.'),
    ('msg.pr_this_pay_item_no_longer_exists', 'msg', N'This pay item no longer exists.', N'بند الراتب هذا لم يعد موجوداً.', N'This pay item no longer exists.'),
    ('msg.pr_this_payroll_calendar_is_inactive', 'msg', N'This payroll calendar is inactive.', N'تقويم الرواتب هذا غير نشط.', N'This payroll calendar is inactive.'),
    ('msg.pr_this_payroll_has_already_been_created', 'msg', N'This payroll has already been created.', N'تم إنشاء هذا المسير مسبقاً.', N'This payroll has already been created.'),
    ('msg.pr_this_payroll_is_not_waiting_for_approval', 'msg', N'This payroll is not waiting for approval.', N'هذا المسير ليس بانتظار الاعتماد.', N'This payroll is not waiting for approval.'),
    ('msg.pr_this_period_is_no_longer_open_for_payrolls', 'msg', N'This period is no longer open for payrolls.', N'هذه الفترة لم تعد مفتوحة للمسيرات.', N'This period is no longer open for payrolls.'),
    ('msg.pr_this_salary_amount_has_an_end_month_it_was_replaced_or_e', 'msg', N'This salary amount has an end month (it was replaced or ended). Change the latest amount instead.', N'لهذا المبلغ شهر انتهاء (استُبدل أو أُنهي). عدّل أحدث مبلغ بدلاً منه.', N'This salary amount has an end month (it was replaced or ended). Change the latest amount instead.'),
    ('msg.pr_this_step_is_not_possible_at_the_payroll_s_current_stage', 'msg', N'This step is not possible at the payroll''s current stage. Refresh the page.', N'هذه الخطوة غير ممكنة في المرحلة الحالية للمسير. حدّث الصفحة.', N'This step is not possible at the payroll''s current stage. Refresh the page.'),
    ('msg.pr_unsupported_action', 'msg', N'Unsupported action.', N'إجراء غير مدعوم.', N'Unsupported action.'),
    ('msg.pr_until_month_must_be_like_2026_12', 'msg', N'Until month must be like 2026-12.', N'يجب أن يكون «حتى شهر» بصيغة 2026-12.', N'Until month must be like 2026-12.'),
    ('msg.pr_use_end_to_stop_a_salary_item', 'msg', N'Use End to stop a salary item.', N'استخدم «إنهاء» لإيقاف بند الراتب.', N'Use End to stop a salary item.'),
    ('msg.pr_validation_re_run', 'msg', N'Validation re-run.', N'أُعيد التحقق.', N'Validation re-run.'),
    ('msg.pr_warning_acknowledged', 'msg', N'Warning acknowledged.', N'تم الإقرار بالتنبيه.', N'Warning acknowledged.'),
