    ('msg.pr_you_are_not_an_approver_for_this_level', 'msg', N'You are not an approver for this level.', N'لست معتمِداً لهذا المستوى.', N'You are not an approver for this level.'),
    ('msg.pr_you_cannot_approve_a_payroll_you_submitted_or_already_ap', 'msg', N'You cannot approve a payroll you submitted or already approved at the previous level.', N'لا يمكنك اعتماد مسير أرسلته أو اعتمدته في المستوى السابق.', N'You cannot approve a payroll you submitted or already approved at the previous level.'),
    ('msg.pr_you_cannot_approve_an_item_you_sent_for_approval_or_alre', 'msg', N'You cannot approve an item you sent for approval or already approved at the previous level.', N'لا يمكنك اعتماد بند أرسلته للاعتماد أو اعتمدته في المستوى السابق.', N'You cannot approve an item you sent for approval or already approved at the previous level.'),
    ('msg.pr_you_do_not_have_permission_to_do_this', 'msg', N'You do not have permission to do this.', N'ليست لديك صلاحية للقيام بذلك.', N'You do not have permission to do this.'),
